% ============================================================
% baseline_nk.mod —— 标准三方程 NK 模型（骨架版）
% 本页只搭结构；FOC 与 steady_state_model 在后续页补完
% ============================================================

// ---------- 1. 变量声明 ----------
var Y C N pi i r mc Y_gap;
%  Y: 产出  C: 消费  N: 就业  pi: 通胀  i: 名义利率
%  r: 实际利率  mc: 实际边际成本  Y_gap: 产出缺口

varexo eps_a eps_m;
%  eps_a: 技术冲击  eps_m: 货币政策冲击

// ---------- 2. 参数声明 ----------
parameters beta sigma phi alpha theta eps_p rho_a rho_i phi_pi phi_y;

% 校准参数（标准 NK 教材值）
beta     = 0.99;     % 季度主观贴现因子 -> 稳态年化实际利率约 4%
sigma    = 1.0;      % CRRA 系数（=1 即 log utility）
phi      = 5.0;      % Frisch 劳动供给弹性的倒数
alpha    = 0.25;     % 生产函数中劳动份额为 (1-alpha)
theta    = 0.75;     % Calvo 不调价概率（平均价格持续 4 季度）
eps_p    = 9.0;      % 中间品替代弹性 -> 稳态加成 1.5 (=9/8)
rho_a    = 0.9;      % 技术冲击 AR(1) 系数
rho_i    = 0.8;      % 利率平滑系数
phi_pi   = 1.5;      % Taylor rule 通胀反应系数（>1 满足 Taylor principle）
phi_y    = 0.5/4;    % Taylor rule 产出缺口反应系数

// ---------- 3. 模型方程（下一页补完 FOC）----------
model;
% --- 家庭欧拉方程（待第 3 页推导后补）---
% 1/C^sigma = beta*(1/r(+1)) * 1/C(+1)^sigma;

% --- 劳动供给（待补）---
% N^phi * C^sigma = w;

% --- 生产函数 ---
Y = A * N^(1-alpha);

% --- 资源约束 ---
Y = C;

% --- Taylor rule ---
i = rho_i*i(-1) + (1-rho_i)*(phi_pi*pi + phi_y*Y_gap) + eps_m;

% --- Fisher equation ---
r = i - pi(+1);

% --- 技术冲击 AR(1) ---
A = rho_a*A(-1) + eps_a;

% --- NKPC（待第 3 页推导后补）---
% pi = beta*pi(+1) + kappa*Y_gap;
end;

// ---------- 4. 稳态（待第 4 页补完）----------
steady_state_model;
  % 见 03-steady-state.html
end;

// ---------- 5. 求解与模拟 ----------
shocks;
var eps_a; stderr 0.01;
var eps_m; stderr 0.0025;
end;

steady;
check;
stoch_simul(irf=20, periods=100);

% ============================================================
% baseline_nk_foc.mod —— 补完 FOC 的 NK 模型
% 上一页骨架中的注释方程，在这里全部写出来
% ============================================================

var Y C N pi i r mc y_gap A;
varexo eps_a eps_m;

parameters beta sigma phi alpha theta eps_p rho_a rho_i phi_pi phi_y kappa;

beta=0.99; sigma=1.0; phi=5.0; alpha=0.25;
theta=0.75; eps_p=9.0;
rho_a=0.9; rho_i=0.8; phi_pi=1.5; phi_y=0.125;

% NKPC 斜率 kappa = (1-theta)(1-beta*theta)/theta * (sigma+phi)
kappa = (1-theta)*(1-beta*theta)/theta * (sigma + phi);

model;
% --- (1) 欧拉方程（对数线性化后的 IS curve）---
%     C_t^-sigma = beta*E[C_{t+1}^-sigma*(1+r)]
%     对数线性化：y_gap = E[y_gap(+1)] - (1/sigma)*(r)
y_gap = y_gap(+1) - (1/sigma)*r;

% --- (2) Fisher equation ---
r = i - pi(+1);

% --- (3) NKPC（产出缺口形式）---
pi = beta*pi(+1) + kappa*y_gap;

% --- (4) Taylor rule ---
i = rho_i*i(-1) + (1-rho_i)*(phi_pi*pi + phi_y*y_gap) + eps_m;

% --- (5) 技术冲击 AR(1) ---
A = rho_a*A(-1) + eps_a;

% --- (6) 自然产出与产出缺口关系（简化）---
%     y_gap 在这里被视为给定内生变量，由 (1)(2)(3)(4) 联立决定
end;

steady_state_model;
  % 见 03-steady-state.html
end;

shocks;
var eps_a; stderr 0.01;
var eps_m; stderr 0.0025;
end;

steady;
check;
stoch_simul(irf=20);

% ============================================================
% solve_ss.m —— 用 fsolve 数值求解 baseline NK 模型稳态
% 内生变量 x = [Y; C; N; w; mc; r; i; pi]
% ============================================================
clear; clc;

% --- 1. 校准参数 ---
p.beta   = 0.99;
p.sigma  = 1.0;
p.phi    = 5.0;
p.alpha  = 0.25;
p.eps    = 9.0;
p.chi    = (1-p.alpha)*(p.eps-1)/p.eps;   % 归一化系数 -> N=1

% --- 2. 定义稳态方程组 ---
ss_eq = @(x) [
    x(1) - x(2);                          % (1) Y = C
    x(1) - x(3)^(1-p.alpha);              % (2) Y = N^(1-alpha), A=1
    p.chi*x(3)^p.phi * x(2)^p.sigma - x(4);   % (3) 劳动供给: chi*N^phi*C^sigma = w
    x(4) - (1-p.alpha)*x(5)*x(3)^(-p.alpha);  % (4) mc = w / ((1-alpha)*N^(-alpha))
    x(5) - (p.eps-1)/p.eps;               % (5) 稳态加成 mc = (eps-1)/eps
    1/p.beta - (1+x(6));                  % (6) 欧拉: 1 = beta*(1+r)
    x(7) - x(6) - x(8);                   % (7) Fisher: i = r + pi
    x(8)                                   % (8) 零通胀稳态 pi = 0
];

% --- 3. 初值 guess ---
x0 = [1; 1; 1; 1; (p.eps-1)/p.eps; 1/p.beta-1; 1/p.beta-1; 0];

% --- 4. fsolve 求解 ---
opts = optimoptions('fsolve','Display','iter','TolFun',1e-10);
[x, fval, exitflag] = fsolve(ss_eq, x0, opts);

% --- 5. 输出 ---
fprintf('\n===== 稳态解 =====\n');
fprintf('Y   = %.6f\n', x(1));
fprintf('C   = %.6f\n', x(2));
fprintf('N   = %.6f\n', x(3));
fprintf('w   = %.6f\n', x(4));
fprintf('mc  = %.6f\n', x(5));
fprintf('r   = %.6f (年化 %.4f%%)\n', x(6), 4*x(6)*100);
fprintf('i   = %.6f\n', x(7));
fprintf('pi  = %.6f\n', x(8));
fprintf('残差范数 = %.2e\n', norm(fval));

% ============================================================
% baseline_nk_ss.mod —— 完整可运行的 baseline NK 模型
% ============================================================

// ---------- 变量 ----------
var Y C N w mc r i pi y_gap;
varexo eps_a eps_m;

// ---------- 参数 ----------
parameters beta sigma phi alpha eps_p chi kappa rho_a rho_i phi_pi phi_y;

beta=0.99; sigma=1.0; phi=5.0; alpha=0.25;
eps_p=9.0;
chi = (1-alpha)*(eps_p-1)/eps_p;     % 归一化 -> N_ss = 1
kappa = (1-0.75)*(1-beta*0.75)/0.75 * (sigma+phi);  % theta=0.75
rho_a=0.9; rho_i=0.8; phi_pi=1.5; phi_y=0.125;

// ---------- 模型方程（对数线性化后）----------
model;
  y_gap = y_gap(+1) - (1/sigma)*r;
  r     = i - pi(+1);
  pi    = beta*pi(+1) + kappa*y_gap;
  i     = rho_i*i(-1) + (1-rho_i)*(phi_pi*pi + phi_y*y_gap) + eps_m;
end;

// ---------- 稳态（关键块）----------
steady_state_model;
  % --- 零通胀归一化稳态 ---
  pi   = 0;
  r    = 1/beta - 1;
  i    = r;
  N    = 1;
  Y    = N^(1-alpha);          % = 1
  C    = Y;
  w    = N^phi * C^sigma / chi;   % 注意归一化 chi
  mc   = (eps_p-1)/eps_p;
  y_gap = 0;
end;

// ---------- 冲击 ----------
shocks;
var eps_a; stderr 0.01;
var eps_m; stderr 0.0025;
end;

// ---------- 求解 ----------
steady;
check;
stoch_simul(irf=20, nograph);

% ===== 你在 model 块里写的是非线性原始方程 =====
model;
  % 家庭 Euler 方程（非线性）
  c^(-sigma) = beta*c(1)^(-sigma)*(1+r);

  % NKPC（由 Calvo 最优定价隐含，这里直接写其等价简化式）
  pi = beta*pi(1) + kappa*mc;

  % Taylor 规则
  (r/r_ss)^rho_r * ((pi/pi_ss)^phi_pi*(y/y_ss)^phi_y)^(1-rho_r) = r/r_ss; % 见下方注释
  r = r(-1)^rho_r * (pi^phi_pi*y^phi_y)^(1-rho_r) * exp(em);

  % 资源约束 / 生产函数 / 技术
  y = c + i;
  y = a*k^alpha*n^(1-alpha);
  a = rho_a*a(-1) + ea;
end;
% Dynare 自动在 steady state 处做一阶泰勒展开，等价于你手推的 hat 变量系统。
% 手推的 hat{c}_t = E_t hat{c}_{t+1} - (1/sigma) hat{r}_t
%   就是 Dynare 对上面 Euler 方程自动求导后的结果。

% ======================================================================
% nk_baseline.mod  标准新凯恩斯三方程模型（含技术与货币政策冲击）
% 运行：在 MATLAB 命令窗口输入  dynare nk_baseline.mod
% ======================================================================

% ---------- 1. 声明内生变量（变量名全小写，与上一节 hat 变量对应）----------
var y c pi r mc a;
%   y   产出(对数偏离)       c   消费(对数偏离)
%   pi  通胀率(对数偏离)     r   名义利率(对数偏离, 总回报)
%   mc  实际边际成本         a   技术冲击(对数偏离)

% ---------- 2. 声明外生结构冲击 ----------
varexo ea em;
%   ea 技术冲击 innovation   em 货币政策冲击 innovation

% ---------- 3. 声明参数并校准 ----------
parameters beta sigma kappa phi_pi phi_y rho_r rho_a sigma_a sigma_m;

beta      = 0.99;     % 主观贴现因子
sigma     = 1.0;      % CRRA 风险厌恶系数(=1 即对数效用)
kappa     = 0.125;    % NKPC 斜率(Calvo 概率 theta=0.75 标定)
phi_pi    = 1.5;      % Taylor 规则对通胀的反应(>1 满足 Taylor 原则)
phi_y     = 0.5/4;    % Taylor 规则对产出的反应
rho_r     = 0.8;      % 利率平滑系数
rho_a     = 0.9;      % 技术冲击 AR(1) 系数
sigma_a   = 0.01;     % 技术冲击标准差
sigma_m   = 0.0025;   % 货币政策冲击标准差

% ---------- 4. 模型方程块（非线性/简化线性混合写法，便于教学）----------
model;
% (1) 家庭 Euler 方程:  c = E_t c(+1) - (1/sigma) * (r - E_t pi(+1))
c = c(1) - (1/sigma)*(r - pi(1));

% (2) 新凯恩斯菲利普斯曲线:  pi = beta*E_t pi(+1) + kappa*mc
pi = beta*pi(1) + kappa*mc;

% (3) 资源约束(无资本)  y = c；边际成本 mc = (sigma+phi)*y （劳动供给简化）
y = c;
mc = (sigma + 1.0)*y;

% (4) Taylor 规则(含利率平滑与货币政策冲击 em)
r = rho_r*r(-1) + (1-rho_r)*(phi_pi*pi + phi_y*y) + em;

% (5) 技术冲击 AR(1):  a = rho_a*a(-1) + ea
a = rho_a*a(-1) + ea;
end;

% ---------- 5. 初始值（全部在稳态附近，这里就是 0 偏离）----------
initval;
y = 0; c = 0; pi = 0; r = 0; mc = 0; a = 0;
end;

% ---------- 6. 求解稳态（本模型稳态就是 0 偏离）----------
steady;

% ---------- 7. 数值导数并检查 Blanchard-Kahn 条件 ----------
check;

% ---------- 8. 随机模拟：一阶近似、200 期 IRF、无图形保存 ----------
stoch_simul(order=1, irf=40, nograph, nodisp);

% ======================================================================
% 运行后在 MATLAB 工作区可见:
%   oo_.irf.ya   -> 技术冲击 ea 对 y 的 40 期脉冲响应
%   oo_.dr.ghx   -> 政策函数对状态变量的一阶导数(政策函数系数)
%   M_.param_names -> 全部参数名
% ======================================================================

estimated_params;
  % --- 结构性参数: 分布, 均值, std, [下界], [上界] ---
  kappa,   gamma_pdf,    0.125, 0.05,    0,    1;   % NKPC 斜率
  sigma_c, normal_pdf,   1.50,  0.37,    0.2,  4;   % 风险厌恶
  h,       beta_pdf,     0.70,  0.10,    0,    0.95;% 习惯形成
  phi_pi,  gamma_pdf,    1.70,  0.10,    1.0,  4;   % Taylor 通胀
  phi_y,   gamma_pdf,    0.125, 0.05,    0,    1;   % Taylor 产出
  rho_r,   beta_pdf,     0.75,  0.10,    0,    0.97;% 利率平滑
  rho_a,   beta_pdf,     0.90,  0.05,    0,    0.999;% 技术 AR(1)
  % --- 冲击标准差: 一律 inv_gamma_pdf ---
  stderr ea, inv_gamma_pdf, 0.01, 0.005;
  stderr em, inv_gamma_pdf, 0.0025, 0.001;
  % --- 可选: 两个冲击的相关系数 ---
  % corr ea, em, beta_pdf, 0.0, 0.2;
end;

% ============================================================
%  bgg_full.mod  ——  在 NK 模型上嵌入 BGG 金融加速器模块
%  新增状态变量: n(企业家净值), q(托宾Q), rk(资本回报)
%  新增外生冲击: efk(外部融资溢价冲击, 即金融冲击)
%  运行:  steady; check; stoch_simul(order=1, irf=40);
% ============================================================

var y c n r w pi k i m rk q l g;
% y产出 c消费 n企业家净值 r名义利率 w实际工资 pi通胀
% k资本存量 i投资 m货币 rk资本实际回报 q托宾Q l就业 g政府支出

varexo eps_a efk eps_g eps_r;
% eps_a技术冲击 efk金融冲击 eps_g政府冲击 eps_r货币政策冲击

varobs y pi i r;

% ---------- 参数声明 ----------
parameters beta sigma phi_pi phi_r rho_a rho_g rho_efk ...
           chi gamma_ent mu k_over_n varphi delta;
beta      = 0.99;      % 家庭主观贴现因子(季度)
sigma     = 1.0;       % 相对风险厌恶
phi_pi    = 1.5;       % 泰勒规则通胀系数
phi_r     = 0.75;      % 泰勒规则利率平滑
rho_a     = 0.90;      % 技术冲击持续性
rho_g     = 0.90;      % 政府支出冲击持续性
rho_efk   = 0.90;      % 金融冲击持续性(BGG关键: 溢价冲击也有持续性)
chi       = 0.05;      % 外部融资溢价对杠杆的弹性(CSV推出, 0.03~0.08)
gamma_ent = 0.9728;    % 企业家存活率(≈平均存活10年)
mu        = 0.12;      % CSV监控/审计成本占资本比例
k_over_n  = 2.0;       % 稳态杠杆 K/N
varphi    = 1.728;     % 投资调整成本强度(对应托宾Q弹性)
delta     = 0.025;     % 季度折旧率

model(linear);
% ---- 家庭 IS 曲线(对数线性化欧拉方程) ----
c(+1) = c - sigma*(r - pi(+1));

% ---- 新凯恩斯菲利普斯曲线 ----
pi = beta*pi(+1) + phi_pi*(1/sigma)*c;

% ---- 货币政策泰勒规则(平滑) ----
r = phi_r*r(-1) + (1-phi_r)*(phi_pi*pi) + eps_r;

% ---- 资本积累方程 ----
k = (1-delta)*k(-1) + delta*i;

% ---- (BGG-1) 托宾Q 方程: 投资需求随 q 上升 ----
q = varphi*(i - k);

% ---- (BGG-2) 外部融资溢价: 杠杆越高, 溢价越贵 ----
%    E_t rk(+1) - r = chi*(q + k(+1) - n) + efk
rk = r + chi*(q + k(+1) - n) + efk;

% ---- (BGG-3) 资本回报定义: 租金+资本利得 ----
rk = (1-delta)*q(+1) + delta*w;

% ---- (BGG-4) 企业家净值演化: n(+1) 由 t 期资本回报与利率决定 ----
%    方括号: 存活企业家的净资产增量 = 资本回报 - 偿债
n(+1) = gamma_ent*( (k_over_n)*(rk + q + k) ...
       - (k_over_n - 1)*r ) ;

% ---- (BGG-5) 金融冲击 AR(1) ----
efk = rho_efk*efk(-1) + efk_shock;

% ---- 外生过程 ----
a   = rho_a*a(-1)  + eps_a;
g   = rho_g*g(-1)  + eps_g;

% ---- 资源约束 ----
y = c + i + g;
end;

% ---------- 稳态初始化(对数线性模型, 全部=0) ----------
initval;
y = 0; c = 0; n = 0; r = 0; w = 0; pi = 0;
k = 0; i = 0; m = 0; rk = 0; q = 0; l = 0; g = 0;
a = 0; efk = 0;
end;

steady;      % 求稳态(对数线性下即为 0)
check;       % 检查BK条件, 列出状态/前瞻变量

% ---------- 随机模拟: 一阶近似, 画40期IRF ----------
stoch_simul(order=1, irf=40) y c i k n rk q efk;
% 对比实验: 把 chi 改成 0 再跑一次, 即得"无摩擦 NK"对照版

% ======================================================================
% plot_irf.m  从 Dynare oo_.irf 画论文级 IRF 图
% 前提: 已运行 dynare nk_baseline.mod, 工作区有 oo_, M_
% ======================================================================
clear; clc; close all;

% --- 1) 取出 IRF: 假设冲击为 ea(技术), 变量为 y, pi, r ---
% Dynare 把 IRF 存在 oo_.irf 下, 字段名 = 变量名_冲击名
horizon = 1:40;                 % 横轴: 40 期
y_irf   = oo_.irf.yea;          % 技术冲击 ea 对 y 的 IRF
pi_irf  = oo_.irf.piea;         % 技术冲击 ea 对 pi 的 IRF
r_irf   = oo_.irf.rea;          % 技术冲击 ea 对 r 的 IRF

% --- 2) 贝叶斯后验: 取 16/50/84 分位数画置信带 ---
% 若用估计命令, 后验 IRF 存在 oo_.PosteriorIRF.metropolis.HPDinf / HPDsup
try
  y_lo = oo_.PosteriorIRF.metropolis.HPDinf.yea;
  y_hi = oo_.PosteriorIRF.metropolis.HPDsup.yea;
catch
  y_lo = y_irf*0.8;  y_hi = y_irf*1.2;   % 校准模型无置信带, 用 ±20% 示意
end

% --- 3) 画三行一列子图 ---
figure('Position',[100 100 700 750]);

subplot(3,1,1);
  fill([horizon fliplr(horizon)], [y_lo fliplr(y_hi)], ...
       [0.85 0.9 0.95],'EdgeColor','none'); hold on;
  plot(horizon, y_irf, 'b-','LineWidth',1.8);
  yline(0,'k:');  title('Output \hat{y}_t');
  ylabel('% dev. from SS');  grid on;

subplot(3,1,2);
  plot(horizon, pi_irf, 'r-','LineWidth',1.8);
  yline(0,'k:');  title('Inflation \hat{\pi}_t');
  ylabel('annualized pp');  grid on;

subplot(3,1,3);
  plot(horizon, r_irf, 'g-','LineWidth',1.8);
  yline(0,'k:');  title('Nominal Rate \hat{r}_t');
  xlabel('Quarters after shock'); ylabel('annualized pp'); grid on;

% --- 4) 导出为论文用 PDF/PNG ---
exportgraphics(gcf,'irf_tech_shock.pdf','ContentType','vector');
exportgraphics(gcf,'irf_tech_shock.png','Resolution',300);
disp('IRF 图已导出 irf_tech_shock.pdf / .png');

% ======================================================================
% 进阶: 把两个模型(无摩擦 vs BGG)叠在一张图对比
% plot(horizon, y_irf_noFric,'b-', horizon, y_irf_BGG,'r--','LineWidth',1.6);
% legend('No friction','BGG accelerator','Location','best');
% ======================================================================

